#!/usr/bin/env python3
"""Offline build/test/benchmark. All generated bytes go to a NEW external directory.
Usage: python3 scripts/reproduce.py --out /tmp/nqc666-run
Requires Rust 1.90+, Cargo, g++, make, objdump, Python 3; zero Cargo dependencies.
"""
import argparse, array, hashlib, json, math, os, pathlib, platform, random, shutil, subprocess, sys, zipfile, tarfile
ROOT=pathlib.Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def stats(values):
    s=sorted(values);n=len(s)
    return {'n':n,**{name:s[math.ceil(n*q)-1] for name,q in [('p50',.5),('p95',.95),('p99',.99),('p99_9',.999)]},
            'max':s[-1],'min':s[0]}
def samples(p):
    a=array.array('Q');a.frombytes(p.read_bytes())
    if sys.byteorder!='little':a.byteswap()
    return a
def run(cmd,cwd,log,env=None):
    with open(log,'w') as f:
        p=subprocess.run(list(map(str,cmd)),cwd=cwd,env=env,stdout=f,stderr=subprocess.STDOUT)
    if p.returncode:raise RuntimeError(f'{cmd}: exit {p.returncode}; see {log}')
def main():
    ap=argparse.ArgumentParser();ap.add_argument('--out',type=pathlib.Path,required=True)
    ap.add_argument('--baseline-existing',type=pathlib.Path)
    ap.add_argument('--refinement',action='store_true',help='final inline comparison: release/fat only')
    a=ap.parse_args();out=a.out.resolve()
    assert not out.is_relative_to(ROOT),'keep build/evidence outside immutable source tree'
    out.mkdir(parents=True,exist_ok=False)
    with tarfile.open(out/'source-snapshot.tar.gz','w:gz') as t:
        for name in ('src','tests','scripts','Cargo.toml','Cargo.lock','PRE_REGISTER.md'):
            t.add(ROOT/name,arcname=name)
    baseline=a.baseline_existing.resolve() if a.baseline_existing else out/'baseline'/'NQC_019'
    archive=ROOT/'historical/NQC_019_CODIGO_Y_MEDICIONES.zip'
    if not a.baseline_existing:
        with zipfile.ZipFile(archive) as z:
            for n in z.namelist():assert (out/'baseline'/n).resolve().is_relative_to(out/'baseline')
            z.extractall(out/'baseline')
        run(['sha256sum','-c','MANIFEST.sha256'],baseline,out/'original-integrity.log')
        run(['python3','verify_results.py'],baseline,out/'original-results.log')
        run(['make','-B','all','test'],baseline,out/'baseline-build-test.log')
        try:run(['make','sanitize'],baseline,out/'baseline-sanitize.log')
        except RuntimeError:
            if 'LeakSanitizer has encountered a fatal error' not in (out/'baseline-sanitize.log').read_text():raise
            e=os.environ.copy();e.update(ASAN_OPTIONS='detect_leaks=0',UBSAN_OPTIONS='halt_on_error=1')
            run(['python3','tests/run_checks.py','--binary','build/sanitized/eval','--output','checks_sanitized_no_lsan.json'],
                baseline,out/'baseline-sanitize-no-lsan.log',e)
        run(['make','benchmark'],baseline,out/'baseline-benchmark.log')
    env=os.environ.copy();env['CARGO_TARGET_DIR']=str(out/'target')
    run(['cargo','test','--offline','--locked'],ROOT,out/'rust-tests.log',env)
    envs={};bins={}
    for variant,profile,flags in [('release','release',''),('thin','thin',''),('fat','fat',''),('native','release','-C target-cpu=native')]:
        if a.refinement and variant not in ('release','fat'):continue
        e=env.copy();e['RUSTFLAGS']=flags;e['CARGO_TARGET_DIR']=str(out/variant)
        run(['cargo','build','--offline','--locked','--profile',profile],ROOT,out/f'build-{variant}.log',e)
        bins[variant]=out/variant/profile/'bench';envs[variant]=e
    evaluator=out/'release/release/eval'
    run(['python3','tests/run_checks.py','--binary',evaluator,'--output','rust-checks.json'],baseline,out/'differential.log')
    raw=(baseline/'inputs/differential.txt').read_bytes()
    cpp=subprocess.check_output([str(baseline/'build/eval')],input=raw)
    rust=subprocess.check_output([str(evaluator)],input=raw)
    assert cpp==rust,'full output parity failed, including partial result fields'
    (out/'full-output-parity.json').write_text(json.dumps({'cases':len(cpp.splitlines()),'all_six_columns_equal':True,'output_sha256':hashlib.sha256(cpp).hexdigest()},indent=2))
    cpu=min(os.sched_getaffinity(0));os.sched_setaffinity(0,{cpu})
    meta={'scope':'OFFLINE_SYNTHETIC_NO_COMMERCIAL_ADMISSION','cpu':subprocess.check_output(['lscpu'],text=True),
      'affinity':sorted(os.sched_getaffinity(0)),'platform':platform.platform(),
      'rustc':subprocess.check_output(['rustc','-vV'],text=True),'g++':subprocess.check_output(['g++','--version'],text=True),
      'clock':'CLOCK_MONOTONIC_RAW; LFENCE/RDTSC/LFENCE calibrated separately',
      'frequency_policy':'uncontrolled virtual machine; no turbo/governor/IRQ changes',
      'cpuinfo':pathlib.Path('/proc/cpuinfo').read_text(),'baseline_archive_sha256':sha(archive),
      'source_sha256':{str(p.relative_to(ROOT)):sha(p) for p in sorted((ROOT/'src').rglob('*.rs'))},
      'binary_sha256':{k:sha(p) for k,p in bins.items()},'runs':[]}
    tasks=[]
    for rep in range(3):
        for variant in bins:
            for mode,corpus,tsc,batch in [('screen','warm_16',0,1),('event_final','warm_16',0,1),
                ('event_reference_final','warm_16',0,1),('compact','warm_16',1,128)]:
                tasks.append((rep,variant,mode,corpus,tsc,batch))
        for mode,corpus,tsc,batch in [('screen','warm_4',0,1),('screen','mixed_16',0,1),
            ('flushed','warm_16',0,1),('packed','warm_16',0,1),('branchy','warm_16',0,1),
            ('packed','warm_16',1,1),('branchy','warm_16',1,1),('branchy','warm_16',1,128),
            ('compact','warm_16',1,1),('compact','warm_16',0,1),('packed','warm_16',1,128),
            ('chain_control','warm_16',1,128),
            ('prepare','warm_16',0,1),('guard','warm_16',0,1),('guard_copy','warm_16',0,1),('eye','warm_16',0,1),
            ('event','warm_16',0,1),('event_reference','warm_16',0,1)]:
            tasks.append((rep,'release',mode,corpus,tsc,batch))
        for corpus in ('warm_4','warm_16','mixed_16','flushed_16'):
            tasks.append((rep,'cpp','flushed' if corpus=='flushed_16' else 'screen',corpus,0,1))
    if a.refinement:
        tasks=[(rep,variant,mode,'warm_16',tsc,batch) for rep in range(3) for variant in bins for mode,tsc,batch in
            [('screen',0,1),('guard',0,1),('event',0,1),('event_final',0,1),('event_reference_final',0,1),
             ('compact_inline',0,1),('compact_inline',1,1),('compact_inline',1,128),('compact',1,128),('chain_control',1,128)]]
        tasks += [(rep,'cpp','screen','warm_16',0,1) for rep in range(3)]
    random.Random(666).shuffle(tasks);(out/'raw').mkdir()
    for rep,variant,mode,corpus,tsc,batch in tasks:
        label=f'{variant}-{mode}-{corpus}-tsc{tsc}-batch{batch}-{rep}';prefix=out/'raw'/label
        count=10000 if batch>1 else (20000 if mode=='flushed' else 200000)
        if variant=='cpp':
            cmd=[baseline/'build/bench',baseline/'inputs'/f'{corpus}.txt',str(count),str(190000+rep),str(int(mode=='flushed')),prefix]
        else:
            cmd=[bins[variant],baseline/'inputs'/f'{corpus}.txt',mode,str(count),str(190000+rep),prefix,str(tsc),str(batch)]
        p=subprocess.run(list(map(str,cmd)),capture_output=True,text=True,check=True)
        info=json.loads(p.stdout);info.setdefault('batch_size',batch);info.setdefault('tsc',bool(tsc))
        raw_samples=samples(prefix.with_suffix('.bin'))
        ratio=sorted(info['tsc_ticks_per_ns'])[2] if tsc else 1
        ns=[x/ratio/batch for x in raw_samples]
        control=samples(pathlib.Path(str(prefix)+'_clock.bin'))
        row={'label':label,'variant':variant,'mode':mode,'corpus':corpus,'rep':rep,'metadata':info,
             'metric':'dependency_chain_batch_mean_ns' if batch>1 else 'individual_call_ns',
             'stats_ns':stats(ns),'raw_stats':stats(raw_samples),'raw_clock_control':stats(control),
             'above_3000_ns':sum(x>3000 for x in ns),'samples_sha256':sha(prefix.with_suffix('.bin')),
             'corpus_sha256':sha(baseline/'inputs'/f'{corpus}.txt')}
        meta['runs'].append(row);print(label,row['stats_ns'],flush=True)
        (out/'benchmark.json').write_text(json.dumps(meta,indent=2)+'\n')
    run(['objdump','-Cd',bins['release']],ROOT,out/'disassembly.txt')
    for name in ['benchmark.json','checks.json','rust-checks.json']:
        shutil.copy2(baseline/'evidence'/name,out/f'baseline-{name}')
    sanitizer=baseline/'evidence/checks_sanitized_no_lsan.json'
    if sanitizer.exists():
        shutil.copy2(sanitizer,out/'baseline-checks_sanitized_no_lsan.json')
        (out/'sanitizer-status.json').write_text(json.dumps({'asan_ubsan':'PASS','leak_sanitizer':'NOT_AVAILABLE_PROC_PTRACE_ENVIRONMENT'},indent=2))
    elif not a.baseline_existing:
        shutil.copy2(baseline/'evidence/checks_sanitized.json',out/'baseline-checks_sanitized.json')
    # Keep raw baseline timing evidence, including calibration and adverse tails.
    with zipfile.ZipFile(out/'baseline-raw.zip','w',zipfile.ZIP_DEFLATED) as z:
        for p in sorted((baseline/'evidence/bench').glob('*.bin')):z.write(p,p.name)
    print(f'COMPLETE {out}')
if __name__=='__main__':main()
